mapper.select:
SELECT COUNT(id) AS orderCount, IFNULL(SUM(amount), 0) AS revenue FROM all_order
deleted = 0
AND create_order_time >= #{reportStartTime}
AND create_order_time <= #{reportEndTime}

select s.name as stationName, count(*) as orderCount from all_order o left join station_info s on o.station_id=s.id where 1=1
and o.create_order_time >= #{reportStartTime}
and o.create_order_time <= #{reportEndTime}
group by s.name

SELECT o.id, o.order_no AS orderNo, o.order_type AS orderType, o.plate_no AS plateNo, o.amount, o.status, s.name AS stationName, o.station_id AS stationId, o.create_order_time AS createTime, o.pay_time AS payTime, o.pay_method AS payMethod, o.discount_amount AS discountAmount FROM all_order o LEFT JOIN station_info s ON o.station_id = s.id AND s.deleted = 0 WHERE o.deleted = 0
AND o.create_order_time >= #{startTime}
AND o.create_order_time <= #{endTime}
ORDER BY o.id DESC

SELECT dp.id, s.name AS stationName, dp.station_id AS stationId, dp.deposit_order_count AS depositOrderCount, dp.status, dp.remark, dp.create_time AS createTime FROM deposit_plan dp LEFT JOIN station_info s ON dp.station_id = s.id AND s.deleted = 0 WHERE dp.deleted = 0
AND dp.create_time >= #{startTime}
AND dp.create_time <= #{endTime}
ORDER BY dp.id DESC
